import unittest

from validate_postgres_ddl import identify_object


class TestIdentifyObject(unittest.TestCase):
    def test_domain_schema_qualified_quoted_in_do_block(self):
        # Format generated by DdlExporter: DO block wrapping the CREATE DOMAIN
        sql = (
            'DO $$\n'
            'BEGIN\n'
            "    IF NOT EXISTS (SELECT 1 FROM pg_type t) THEN\n"
            "        EXECUTE 'CREATE DOMAIN public.\"varchar20\" AS VARCHAR(20);';\n"
            '    END IF;\n'
            'END $$;'
        )
        self.assertEqual(identify_object(sql), ('DOMAIN', 'varchar20'))

    def test_domain_plain_quoted(self):
        self.assertEqual(identify_object('CREATE DOMAIN "meu_dominio" AS INTEGER;'),
                         ('DOMAIN', 'meu_dominio'))

    def test_domain_bare_unquoted(self):
        self.assertEqual(identify_object('CREATE DOMAIN MEU_DOMINIO AS INTEGER;'),
                         ('DOMAIN', 'MEU_DOMINIO'))

    def test_domain_with_hyphen(self):
        self.assertEqual(identify_object("CREATE DOMAIN public.\"e-mail\" AS VARCHAR(50);"),
                         ('DOMAIN', 'e-mail'))

    def test_view(self):
        self.assertEqual(
            identify_object('DROP VIEW IF EXISTS "MINHA_VIEW" CASCADE;\nCREATE VIEW "MINHA_VIEW" AS SELECT 1;'),
            ('VIEW', 'MINHA_VIEW'))

    def test_function(self):
        sql = ('CREATE FUNCTION "minha_func"() RETURNS void AS $$\n'
               'BEGIN\n'
               'END;\n'
               '$$ LANGUAGE plpgsql;')
        self.assertEqual(identify_object(sql), ('FUNCTION', 'minha_func'))

    def test_trigger(self):
        self.assertEqual(
            identify_object('DROP TRIGGER IF EXISTS "TRG_X" ON "tabela";\n'
                            'CREATE TRIGGER "TRG_X" BEFORE INSERT ON "tabela" FOR EACH ROW EXECUTE FUNCTION f();'),
            ('TRIGGER', 'TRG_X'))

    def test_other_statement(self):
        self.assertEqual(identify_object('SELECT 1;'), ('OTHER', 'UNKNOWN'))


class TestRunDdlValidation(unittest.TestCase):
    def test_apply_changes_rolls_back_when_any_statement_fails(self):
        import tempfile
        from unittest.mock import MagicMock
        from validate_postgres_ddl import run_ddl_validation

        with tempfile.NamedTemporaryFile('w', suffix='.sql', delete=False) as f:
            f.write('DROP VIEW IF EXISTS "v" CASCADE;\nCREATE VIEW "v" AS INVALID_SYNTAX;\n')
            fpath = f.name

        try:
            mock_conn = MagicMock()
            mock_cursor = MagicMock()
            mock_conn.cursor.return_value = mock_cursor

            # First statement succeeds, second fails
            def execute_side_effect(sql):
                if 'INVALID_SYNTAX' in sql:
                    raise Exception("syntax error at or near 'INVALID_SYNTAX'")

            mock_cursor.execute.side_effect = execute_side_effect

            results, _ = run_ddl_validation(mock_conn, [fpath], apply_changes=True)
            self.assertEqual(len(results), 2)
            self.assertTrue(results[0].success)
            self.assertFalse(results[1].success)

            mock_conn.rollback.assert_called()
            mock_conn.commit.assert_not_called()
        finally:
            import os
            os.remove(fpath)

    def test_apply_changes_commits_when_all_statements_succeed(self):
        import tempfile
        from unittest.mock import MagicMock
        from validate_postgres_ddl import run_ddl_validation

        with tempfile.NamedTemporaryFile('w', suffix='.sql', delete=False) as f:
            f.write('SELECT 1;\nSELECT 2;\n')
            fpath = f.name

        try:
            mock_conn = MagicMock()
            mock_cursor = MagicMock()
            mock_conn.cursor.return_value = mock_cursor

            results, _ = run_ddl_validation(mock_conn, [fpath], apply_changes=True)
            self.assertEqual(len(results), 2)
            self.assertTrue(all(r.success for r in results))

            mock_conn.commit.assert_called_once()
        finally:
            import os
            os.remove(fpath)

    def test_run_ddl_validation_safe_against_strict_connection_and_ensures_cleanup(self):
        import tempfile
        from unittest.mock import MagicMock
        from validate_postgres_ddl import run_ddl_validation

        with tempfile.NamedTemporaryFile('w', suffix='.sql', delete=False) as f:
            f.write('SELECT 1;\n')
            fpath = f.name

        try:
            # Emulate real C extension connection that rejects arbitrary attribute assignment
            class StrictConnection:
                def __init__(self, cursor):
                    self.autocommit = False
                    self._cursor = cursor
                    self.rolled_back = False
                    self.committed = False

                def cursor(self):
                    return self._cursor

                def rollback(self):
                    self.rolled_back = True

                def commit(self):
                    self.committed = True

                def __setattr__(self, name, value):
                    if name in ('autocommit', '_cursor', 'rolled_back', 'committed'):
                        super().__setattr__(name, value)
                    else:
                        raise AttributeError(f"'{type(self).__name__}' object has no attribute '{name}'")

            mock_cursor = MagicMock()
            strict_conn = StrictConnection(mock_cursor)

            results, runtime_issues = run_ddl_validation(strict_conn, [fpath], apply_changes=False)
            self.assertEqual(len(results), 1)
            self.assertTrue(results[0].success)
            self.assertTrue(strict_conn.rolled_back)
            mock_cursor.close.assert_called_once()
        finally:
            import os
            os.remove(fpath)

    def test_print_diagnostic_report_empty_returns_false(self):
        from validate_postgres_ddl import print_diagnostic_report
        self.assertFalse(print_diagnostic_report([]))

    def test_run_ddl_validation_missing_target_file_fails(self):
        from unittest.mock import MagicMock
        from validate_postgres_ddl import run_ddl_validation, print_diagnostic_report
        mock_conn = MagicMock()
        results, _ = run_ddl_validation(mock_conn, ["/nonexistent/missing_dump.sql"])
        self.assertEqual(len(results), 1)
        self.assertFalse(results[0].success)
        self.assertEqual(results[0].pg_code, "FILE_NOT_FOUND")
        self.assertFalse(print_diagnostic_report(results))

    def test_run_ddl_validation_empty_target_file_fails_by_default(self):
        import tempfile, os
        from unittest.mock import MagicMock
        from validate_postgres_ddl import run_ddl_validation, print_diagnostic_report
        with tempfile.NamedTemporaryFile("w+", suffix=".sql", delete=False) as f:
            f.write("-- comment only\n")
            temp_path = f.name
        self.addCleanup(os.remove, temp_path)

        mock_conn = MagicMock()
        results, _ = run_ddl_validation(mock_conn, [temp_path], allow_empty_files=False)
        self.assertEqual(len(results), 1)
        self.assertFalse(results[0].success)
        self.assertEqual(results[0].pg_code, "FILE_EMPTY")
        self.assertFalse(print_diagnostic_report(results))


def check_live_postgres_available() -> bool:
    try:
        from config import get_postgres_connection, PostgresConfig
        cfg = PostgresConfig()
        conn = get_postgres_connection(cfg)
        cur = conn.cursor()
        cur.execute("SELECT 1;")
        res = cur.fetchone()
        conn.close()
        return bool(res and res[0] == 1)
    except Exception:
        return False


HAS_REAL_PG = check_live_postgres_available()


@unittest.skipUnless(HAS_REAL_PG, "Live PostgreSQL instance required for full regression tests")
class TestValidatePostgresDdlRegression(unittest.TestCase):
    """
    Regression tests calling the complete public validate_postgres_ddl() function
    against a real PostgreSQL database with a disposable schema.
    Verifies return values, diagnostic report output, connection ownership,
    and PostgreSQL catalog state across dry-run and apply modes.
    """

    def setUp(self):
        from config import get_postgres_connection
        self.conn = get_postgres_connection()
        self.schema_name = "test_disposable_val"
        cur = self.conn.cursor()
        cur.execute(f"DROP SCHEMA IF EXISTS {self.schema_name} CASCADE;")
        cur.execute(f"CREATE SCHEMA {self.schema_name};")
        cur.execute(f"SET search_path TO {self.schema_name}, public;")
        self.conn.commit()

    def tearDown(self):
        if self.conn and not self.conn.closed:
            try:
                cur = self.conn.cursor()
                cur.execute(f"DROP SCHEMA IF EXISTS {self.schema_name} CASCADE;")
                self.conn.commit()
            except Exception:
                pass
            finally:
                self.conn.close()

    def test_complete_public_function_valid_ddl_dry_run_never_persists(self):
        import tempfile, os
        from validate_postgres_ddl import validate_postgres_ddl

        with tempfile.NamedTemporaryFile("w+", suffix=".sql", delete=False) as f:
            f.write("CREATE TABLE reg_dry_run_table (id INT PRIMARY KEY, name VARCHAR(50));\n")
            fpath = f.name
        self.addCleanup(os.remove, fpath)

        success = validate_postgres_ddl(
            pg_connection=self.conn,
            target_files=[fpath],
            apply_changes=False
        )
        self.assertTrue(success)
        # Caller's connection must remain open and under caller responsibility
        self.assertFalse(self.conn.closed)

        # Verify catalog: table must NOT have been persisted in dry-run mode
        cur = self.conn.cursor()
        cur.execute(
            f"SELECT 1 FROM information_schema.tables "
            f"WHERE table_schema = '{self.schema_name}' AND table_name = 'reg_dry_run_table';"
        )
        self.assertIsNone(cur.fetchone())

    def test_complete_public_function_valid_ddl_apply_persists_in_catalog(self):
        import tempfile, os
        from validate_postgres_ddl import validate_postgres_ddl

        with tempfile.NamedTemporaryFile("w+", suffix=".sql", delete=False) as f:
            f.write("CREATE TABLE reg_apply_table (id INT PRIMARY KEY, name VARCHAR(50));\n")
            fpath = f.name
        self.addCleanup(os.remove, fpath)

        success = validate_postgres_ddl(
            pg_connection=self.conn,
            target_files=[fpath],
            apply_changes=True
        )
        self.assertTrue(success)
        self.assertFalse(self.conn.closed)

        # Verify catalog: table MUST have been persisted in apply mode
        cur = self.conn.cursor()
        cur.execute(
            f"SELECT 1 FROM information_schema.tables "
            f"WHERE table_schema = '{self.schema_name}' AND table_name = 'reg_apply_table';"
        )
        row = cur.fetchone()
        self.assertIsNotNone(row)
        self.assertEqual(row[0], 1)

    def test_complete_public_function_invalid_ddl_apply_reverts_all_changes(self):
        import tempfile, os
        from validate_postgres_ddl import validate_postgres_ddl

        with tempfile.NamedTemporaryFile("w+", suffix=".sql", delete=False) as f:
            # Statement 1 valid, Statement 2 syntax error
            f.write(
                "CREATE TABLE reg_first_ok (id INT PRIMARY KEY);\n"
                "CREATE TABLE reg_second_bad (id INT INVALID_SYNTAX);\n"
            )
            fpath = f.name
        self.addCleanup(os.remove, fpath)

        success = validate_postgres_ddl(
            pg_connection=self.conn,
            target_files=[fpath],
            apply_changes=True
        )
        self.assertFalse(success)
        self.assertFalse(self.conn.closed)

        # Verify catalog: all changes rolled back; Statement 1 must NOT exist
        cur = self.conn.cursor()
        cur.execute(
            f"SELECT 1 FROM information_schema.tables "
            f"WHERE table_schema = '{self.schema_name}' AND table_name = 'reg_first_ok';"
        )
        self.assertIsNone(cur.fetchone())

    def test_complete_public_function_report_signature_and_runtime_issues_formatting(self):
        from validate_postgres_ddl import print_diagnostic_report, ValidationResult, SQLStatement

        stmt = SQLStatement("test.sql", "FUNCTION", "sp_demo", "SELECT 1;", 1)
        results = [ValidationResult(stmt, success=True)]
        runtime_issues = [("sp_demo", "Line 4: table test does not exist")]

        # Calling print_diagnostic_report with runtime_issues must succeed without TypeError
        ret = print_diagnostic_report(results, runtime_issues=runtime_issues)
        self.assertTrue(ret)

    def test_presentation_failure_does_not_claim_rollback_when_committed(self):
        import tempfile, os
        from unittest.mock import patch
        from validate_postgres_ddl import validate_postgres_ddl

        with tempfile.NamedTemporaryFile("w+", suffix=".sql", delete=False) as f:
            f.write("CREATE TABLE reg_tbl_pres (id INT PRIMARY KEY);\n")
            fpath = f.name
        self.addCleanup(os.remove, fpath)

        # Simulate presentation failure after successful commit
        with patch('validate_postgres_ddl.print_diagnostic_report', side_effect=RuntimeError("Formatting crash")):
            import io
            from contextlib import redirect_stdout
            out = io.StringIO()
            with redirect_stdout(out):
                success = validate_postgres_ddl(
                    pg_connection=self.conn,
                    target_files=[fpath],
                    apply_changes=True
                )
            self.assertFalse(success)
            output_str = out.getvalue()
            # Must accurately indicate changes WERE committed, not that a rollback occurred
            self.assertIn("changes WERE committed", output_str)
            self.assertNotIn("rolled back all changes", output_str)


if __name__ == '__main__':
    unittest.main()
